"""Complete 24 original cardiovascular-examination questions."""
from create_exam_cardiac_signs import rows,q,JV,HS,CE,ref
from qbank_authoring import finalize
SM=ref('Clinical Methods: systolic murmurs','https://www.ncbi.nlm.nih.gov/books/NBK345/')

q('A patient has a harsh late-peaking systolic murmur at the right upper sternal border radiating to the carotids, with a slow-rising pulse. Which lesion best fits?', 'Aortic stenosis',[
 ('Mitral regurgitation','This more often produces an apical holosystolic murmur radiating toward the axilla.'),('Pulmonary stenosis','Its location and radiation more strongly involve the left upper sternal area.'),('Ventricular septal defect','This more often produces a lower-sternal holosystolic murmur.')],
 'Combine timing, radiation and the arterial pulse','**Fixed LV outflow obstruction can delay the upstroke and produce an ejection murmur.**',['Murmur intensity alone does not reliably quantify severity.','Low flow can make severe disease less loud.'],'**Confirm severity and ventricular response with echo.**',['Assess syncope, angina and dyspnea.','Do not use a soft murmur to dismiss severe low-flow disease.'],[['Timing','Ejection systolic'],['Radiation','Carotids'],['Pulse','Slow rising']],[CE,SM],style='clinical_scenario')

q('Which maneuver best accentuates a soft aortic-regurgitation murmur?', 'Listen with the diaphragm along the left sternal border while the patient leans forward at end expiration',[
 ('Use the bell only at the apex in left lateral position','This is more useful for a low-pitched mitral diastolic rumble.'),('Listen only over the carotid artery during inspiration','This does not optimize the AR murmur.'),('Apply very firm bell pressure to detect only low frequencies','Firm pressure makes the bell behave more like a diaphragm.')],
 'Match position and stethoscope technique to sound frequency','**AR typically creates a high-pitched early diastolic decrescendo sound.**',['Aortic-root and valve anatomy can affect the best location.','A quiet room and short repeated listening improve detection.'],'**Integrate pulse pressure and other signs without requiring them.**',['Acute severe AR may lack the classic chronic peripheral findings.','Echo establishes mechanism and severity.'],[['AR','High-pitched early diastolic'],['Technique','Diaphragm/end expiration/forward'],['MS','Bell at apex/left lateral']],[CE])

q('A blowing holosystolic murmur is loudest at the apex and radiates to the axilla. Which lesion is most likely?', 'Mitral regurgitation',[
 ('Aortic stenosis','Its typical murmur is ejection systolic with carotid radiation.'),('Mitral stenosis','Its characteristic murmur is diastolic.'),('Pulmonary regurgitation','Its murmur is early diastolic, usually at the upper left sternal border.')],
 'Regurgitant flow can occupy the whole systolic interval','**An LV-to-LA pressure gradient can persist from S1 to S2.**',['Jet direction and mechanism can alter radiation.','Associated S3 and a displaced apex may reflect chronic volume loading.'],'**Assess the mechanism and severity with echocardiography.**',['Do not infer severity from loudness alone.','Acute regurgitation can have a different bedside presentation.'],[['Timing','Holosystolic'],['Site','Apex'],['Usual radiation','Axilla']],[CE,SM],style='clinical_scenario')

q('A lower-left-sternal holosystolic murmur becomes louder during inspiration. Which lesion is favored?', 'Tricuspid regurgitation',[
 ('Mitral regurgitation','Left-sided murmurs usually do not show the same inspiratory augmentation.'),('Aortic stenosis','The location and timing pattern differ.'),('Mitral stenosis','This is a diastolic lesion.')],
 'Respiration modifies right- and left-sided filling','**Inspiration increases right-sided venous return in spontaneous breathing.**',['The intensity response is supportive rather than infallible.','Look for large jugular systolic waves and hepatic pulsation.'],'**Correlate with right-heart and valve imaging.**',['Severe low-flow states can alter murmur behavior.','Consider pulmonary pressures and RV function.'],[['Murmur','Lower-sternal holosystolic'],['Inspiration','Often louder'],['Associated signs','Venous systolic reflux']],[SM,CE],style='clinical_scenario')

q('A low-pitched apical mid-diastolic rumble with an opening snap is best heard with the bell in the left lateral position. Which lesion best fits?', 'Mitral stenosis',[
 ('Aortic regurgitation without a secondary apical rumble','The primary AR sound is higher-pitched and early diastolic.'),('Mitral regurgitation','Its primary murmur is systolic.'),('Pulmonary stenosis','Its primary murmur is ejection systolic at the upper left sternal border.')],
 'Timing and frequency localize the flow problem','**Obstructed diastolic mitral inflow produces the low-frequency rumble.**',['An opening snap suggests a mobile stenotic valve but may be absent with heavy calcification.','Presystolic accentuation depends on atrial contraction and is lost in AF.'],'**Assess valve anatomy and pressure consequences with echo.**',['Duration and associated findings can inform suspicion but do not replace quantification.','Review rheumatic and other causes.'],[['Timing','Diastolic'],['Sound','Opening snap/rumble'],['Technique','Bell, light pressure, left lateral']],[CE])

q('A systolic murmur becomes louder during Valsalva strain and standing, but softer with squatting. Which mechanism is favored?', 'Dynamic LV outflow obstruction in hypertrophic cardiomyopathy',[
 ('Fixed valvular aortic stenosis as the typical response','Reduced preload usually makes the AS murmur softer.'),('Mitral regurgitation as uniquely established by the response','The classic preload-dependent increase points more strongly to dynamic obstruction.'),('A patent ductus arteriosus','Its characteristic murmur is continuous rather than this ejection pattern.')],
 'A smaller LV cavity can increase dynamic obstruction','**Reduced preload can intensify HCM outflow turbulence.**',['Squatting increases venous return and afterload, often reducing the murmur.','Other findings and the quality/location of the murmur matter.'],'**Confirm with echo and assess the full HCM phenotype.**',['Avoid unsupervised provocative maneuvers in an unstable patient.','Do not diagnose genetic HCM from murmur response alone.'],[['Standing/Valsalva strain','Less preload; often louder HCM'],['Squatting','More filling; often softer HCM'],['AS','Usually different preload response']],[SM],style='clinical_scenario')

q('In mitral valve prolapse, what usually happens to the click when the patient stands from squatting?', 'It moves earlier in systole as LV volume decreases',[
 ('It moves later because LV filling increases','Standing reduces rather than increases the relevant preload.'),('It becomes a diastolic opening snap','These are different sounds and mechanisms.'),('Its timing is independent of ventricular volume','MVP timing is characteristically volume-sensitive.')],
 'Leaflet prolapse timing depends on chamber geometry','**A smaller LV reaches the prolapse configuration earlier.**',['The associated late-systolic murmur can lengthen.','Squatting typically shifts the click later.'],'**Use maneuvers to clarify an uncertain sound.**',['Echo evaluates anatomy and regurgitation.','Not every midsystolic sound represents prolapse.'],[['Standing','Earlier click'],['Squatting','Later click'],['Mechanism','LV volume changes']],[SM])

q('A continuous murmur with systolic accentuation is heard below the left clavicle in a compatible congenital setting. Which lesion is most likely?', 'Patent ductus arteriosus',[
 ('An uncomplicated small VSD','This usually produces a systolic murmur rather than a truly continuous one.'),('Aortic stenosis','Its murmur ends with systole.'),('Mitral stenosis','Its main murmur is diastolic.')],
 'Continuous flow requires a pressure gradient across systole and diastole','**Aortic-to-pulmonary flow through a ductus can persist throughout the cycle.**',['Pulmonary hypertension can alter or abolish the classic continuous pattern.','Other continuous murmurs exist and require localization.'],'**Confirm the anatomy and hemodynamics.**',['Assess pulse findings and pulmonary vascular consequences.','Do not assume the classic sound remains present in advanced disease.'],[['Timing','Continuous'],['Gradient','Aorta to pulmonary artery'],['Advanced PH','Can alter murmur']],[CE],style='clinical_scenario')

q('A small restrictive VSD has a very loud lower-sternal holosystolic murmur. Which statement is correct?', 'Murmur loudness does not mean the defect or shunt is necessarily large',[
 ('The loudest VSD murmur always indicates the largest shunt','A small high-velocity jet can be loud.'),('A large nonrestrictive defect must always be louder','Lower pressure gradients can produce less turbulence.'),('The murmur directly measures pulmonary vascular resistance','Hemodynamic assessment requires more information.')],
 'Sound intensity reflects turbulence and gradients','**A restrictive opening can create a high-velocity audible jet.**',['Large defects and elevated pulmonary pressure can reduce the gradient.','Symptoms and chamber loading determine clinical significance.'],'**Use echo rather than loudness alone to assess the lesion.**',['Look for a thrill and associated flow findings.','Assess pulmonary pressure and volume burden.'],[['Small restrictive','Can be very loud'],['Large/nonrestrictive','Not necessarily louder'],['Severity','Shunt and hemodynamics']],[SM,CE],style='clinical_scenario')

q('Which feature should prompt further evaluation rather than reassurance that a systolic murmur is innocent?', 'Exertional syncope with a pathological pulse or other abnormal cardiac findings',[
 ('A soft short systolic murmur in an otherwise well person with a normal examination','This may be a benign flow pattern, though context matters.'),('A murmur that decreases with reduced flow without symptoms','This alone does not establish dangerous structural disease.'),('A normal second sound and no other abnormal findings','These are more reassuring than the red-flag option.')],
 'The murmur is part of a cardiovascular syndrome','**Symptoms, timing, intensity, radiation and associated signs determine concern.**',['Diastolic and clearly pathological patterns warrant assessment.','A soft murmur does not exclude severe disease when flow is low.'],'**Arrange appropriate cardiac evaluation.**',['Urgency depends on the symptom and stability.','Do not label a murmur innocent solely because the patient is young.'],[['Reassuring context','Asymptomatic/normal associated findings'],['Red flag','Exertional syncope'],['Action','Structural/rhythm assessment']],[CE])

q('A patient develops acute pulmonary edema and shock after MI, but the new apical systolic murmur is short and not very loud. Which conclusion is appropriate?', 'Acute severe mitral regurgitation remains possible and requires urgent echocardiography',[
 ('A soft murmur excludes severe regurgitation','Rapid pressure equalization and low output can reduce murmur intensity/duration.'),('Only a chronic valvular lesion can cause pulmonary edema','Acute mechanical complications can be severe.'),('A normal-sized apex excludes an acute severe lesion','Chamber enlargement may not yet have developed.')],
 'Acute hemodynamics can hide a dramatic lesion','**Severe acute MR can produce shock before chronic examination signs appear.**',['Papillary muscle dysfunction or rupture is a key post-MI concern.','Other mechanical complications also require urgent assessment.'],'**Use immediate bedside echo and definitive specialist care.**',['Support oxygenation and circulation while clarifying the mechanism.','Do not wait for a textbook-loud murmur.'],[['Acute MR','May be soft/short'],['Chronic signs','May be absent'],['Priority','Urgent echo and support']],[CE],style='clinical_scenario')

q('A patient with clear aortic-regurgitation signs also has an apical mid-diastolic rumble without a convincing opening snap. Which explanation should be considered?', 'An Austin Flint murmur from severe AR rather than assuming anatomical mitral stenosis',[
 ('Every apical diastolic rumble proves rheumatic mitral stenosis','AR can create a functional mitral-inflow disturbance.'),('The sound establishes an ASD','ASD has a different characteristic examination pattern.'),('A diastolic rumble excludes aortic regurgitation','The two can coexist through the Austin Flint mechanism.')],
 'A sound can be generated by flow interaction rather than primary valve narrowing','**Severe AR can produce an apical rumble.**',['Look for the primary AR murmur and peripheral/contextual findings.','Anatomical MS can coexist and must be distinguished.'],'**Use echo to assess both valves and the regurgitant lesion.**',['Do not infer the exact mechanism or severity from one sound alone.','Integrate timing, opening snap and valve anatomy.'],[['MS','Anatomical inflow obstruction'],['Austin Flint','AR-associated apical rumble'],['Confirmation','Echo of both valves']],[CE],style='clinical_scenario')

if __name__=='__main__':finalize('Clinical Examination',2,'Cardiovascular Examination','exam-cardiac',rows,24)
